export const $=s=>document.querySelector(s);

export const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

export const clamp=(n,a=0,b=100)=>Math.max(a,Math.min(b,n));

export const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;

export function notify(msg){notify.lastMessage=msg;$('#notice').textContent=uiText(msg);$('#notice').style.display='block';clearTimeout(game.noticeTimer);game.noticeTimer=setTimeout(()=>$('#notice').style.display='none',3500)}

export function modal(html){$('#modalBody').innerHTML=translateHtml(html);if(!$('#modal').open)$('#modal').showModal()}

export function deltaText(d){return Object.entries(d).filter(([,v])=>v).map(([k,v])=>`${v>0?'+':''}${v} ${LABELS[k]}`).join(' · ')||'Sin cambio directo'}

export function sourceDialog(){modal(`<p class="eyebrow">BIBLIOTECA DE LA MISIÓN</p><h2>La ciencia detrás del juego.</h2><p>Hechos contrastados con páginas oficiales de NASA. Las unidades de recursos, precios, daños y recompensas son reglas educativas del simulador. La misión, su ruta y los incidentes son ficticios; el encuentro con asteroides es una actividad didáctica, no una ruta real de Artemis.</p>${Object.entries(SOURCES).map(([k,s])=>`<div class="source-row"><a href="${s.url}" target="_blank" rel="noopener">${esc(s.title)} ↗</a><p>${esc(s.fact)}</p></div>`).join('')}<p class="mini">Sin afiliación ni certificación de NASA. Preparado como prototipo educativo para Space Apps. Consulta el reto y sus requisitos antes de presentar.</p>`)}

export function art(type,seed=0){let d='';const c=['#91dbff','#ffae73','#89e6bd','#b7aaff'][seed%4];switch(type){
case'ship':case'fire':d=`<g class="float"><path d="M70 85V44l20-25 20 25v41Z" fill="#d2e0ec" stroke="${c}" stroke-width="2"/><path d="M70 64h40" stroke="#e79b64" stroke-width="9"/><rect x="80" y="42" width="20" height="16" rx="5" fill="#173955"/><path d="m77 88 6 18 7-10 7 10 6-18" fill="#ffae73"/><path d="m70 71-15 19h15m40-19 15 19h-15" fill="#94b2c9"/></g>`;break;
case'solar':d=`<g class="float"><rect x="19" y="37" width="58" height="39" rx="2" fill="#173b5c" stroke="${c}"/><rect x="103" y="37" width="58" height="39" rx="2" fill="#173b5c" stroke="${c}"/><path d="M38 37v39m20-39v39m65-39v39m20-39v39M19 56h58m26 0h58M77 57h26" stroke="${c}"/><rect x="81" y="40" width="18" height="47" fill="#d3dfeb"/><circle cx="145" cy="20" r="8" fill="#ffd393"/></g>`;break;
case'power':case'battery':d=`<rect x="57" y="29" width="66" height="69" rx="10" fill="#1d3b50" stroke="${c}" stroke-width="3"/><path d="M76 23h28" stroke="#d6e6f0" stroke-width="7"/><path d="m94 41-17 26h14l-4 20 20-30H94l5-16Z" fill="#ffdc66"/>`;break;
case'oxygen':case'fuel':d=`<rect x="46" y="28" width="32" height="70" rx="15" fill="#a5bfce"/><rect x="99" y="28" width="32" height="70" rx="15" fill="#b9d2de"/><path d="M62 21v11m53-11v11m-55 38h20m19 0h31" stroke="${c}" stroke-width="5"/><text x="52" y="62" fill="#17364c" font-size="17">${type==='fuel'?'Δv':'O₂'}</text><text x="105" y="62" fill="#17364c" font-size="17">${type==='fuel'?'Δv':'O₂'}</text>`;break;
case'filter':case'recycle':case'water':d=`<path class="float" d="M90 22c-15 23-30 39-30 51a30 30 0 0 0 60 0c0-12-15-28-30-51Z" fill="#173d59" stroke="${c}" stroke-width="3"/><path d="M76 75q1 12 12 13" stroke="white" stroke-width="3" fill="none"/><path d="M39 32 29 45l13 1m-8-5q12-26 33-24m70 70 9-11-13-2m9 7q-13 25-34 23" stroke="#89e6bd" fill="none" stroke-width="3"/>`;break;
case'antenna':case'satellite':case'signal':d=`<path d="M65 47q21 40 49 0Z" fill="#b4c8da" stroke="${c}" stroke-width="2"/><path d="m87 66-12 30h30L93 66m-3-9 18-25M64 101h50" fill="none" stroke="#8cacc6" stroke-width="5"/><path d="M107 23q20 0 20 21m-17-32q28 0 28 29" stroke="${c}" stroke-width="2" fill="none"/>`;break;
case'shield':d=`<path class="float" d="m90 21 35 14v29c0 22-18 34-35 43-17-9-35-21-35-43V35Z" fill="#173b4f" stroke="${c}" stroke-width="3"/><path d="m73 60 12 12 24-24" stroke="#89e6bd" fill="none" stroke-width="5"/>`;break;
case'tools':d=`<path d="M109 24a22 22 0 0 0-28 27L53 81a11 11 0 0 0 16 15l29-31a22 22 0 0 0 26-28l-17 17-14-14Z" fill="#b9ccde" stroke="${c}" stroke-width="2"/><circle cx="62" cy="88" r="4" fill="#172d42"/>`;break;
case'camera':d=`<rect x="43" y="41" width="95" height="58" rx="10" fill="#48627a" stroke="${c}" stroke-width="2"/><path d="m64 41 8-12h33l8 12" fill="#a0bbcf"/><circle cx="90" cy="69" r="22" fill="#071b2c" stroke="${c}" stroke-width="4"/><circle cx="90" cy="69" r="12" fill="#246088"/><circle cx="84" cy="63" r="5" fill="#b4eaff"/>`;break;
case'drill':d=`<path d="M60 30h50v26H60Z" fill="#ffae73"/><path d="M94 56v43m-13-34 26 8-26 8 26 8-13 13M56 102h70" stroke="${c}" stroke-width="4" fill="none"/><path d="M49 58v42h19V58" fill="#688ca6"/>`;break;
case'moon':case'ice':d=`<circle class="float" cx="90" cy="61" r="40" fill="${type==='ice'?'#8fbbc9':'#879bb0'}"/><circle cx="77" cy="45" r="10" fill="#556c84"/><circle cx="107" cy="67" r="14" fill="#657d95"/><circle cx="76" cy="83" r="6" fill="#c2d2df"/><path d="M91 21a40 40 0 0 1 0 80c21-28 17-55 0-80" fill="#172b44" opacity=".7"/>`;break;
case'orbit':d=`<ellipse class="rotate" cx="90" cy="60" rx="64" ry="30" fill="none" stroke="${c}" stroke-dasharray="4 5"/><circle cx="90" cy="60" r="20" fill="#4d779d"/><circle cx="146" cy="46" r="6" fill="#ffae73"/>`;break;
case'sun':d=`<g class="rotate"><circle cx="90" cy="60" r="29" fill="#ffba68"/><path d="M90 14v10m0 72v10M44 60h10m72 0h10M57 27l8 8m50 50 8 8M57 93l8-8m50-50 8-8" stroke="#ffae73" stroke-width="4"/></g>`;break;
case'habitat':case'airlock':d=`<path d="M36 94V64a54 54 0 0 1 108 0v30Z" fill="#a8bed0" stroke="${c}" stroke-width="2"/><path d="M77 93V57h27v36" fill="#1a354e"/><rect x="49" y="58" width="17" height="15" fill="#36799d"/><rect x="114" y="58" width="17" height="15" fill="#36799d"/><path d="M26 97h128" stroke="#7691a9" stroke-width="4"/>`;break;
case'rover':d=`<path d="M48 60h80v24H48Z" fill="#d1dfe9"/><circle cx="58" cy="90" r="12" fill="#2a4055" stroke="${c}" stroke-width="3"/><circle cx="119" cy="90" r="12" fill="#2a4055" stroke="${c}" stroke-width="3"/><path d="M84 60V32h28m-15 0 18-12" stroke="#c4d7e6" stroke-width="4"/><rect x="63" y="46" width="22" height="14" fill="#649cc0"/>`;break;
case'astronaut':d=`<circle cx="90" cy="39" r="21" fill="#dce7ee"/><rect x="73" y="30" width="34" height="18" rx="9" fill="#14374e"/><path d="M72 59h36v31H72Z" fill="#dce7ee"/><path d="M76 86v23m28-23v23M72 66 57 82m51-16 15 16" stroke="#dce7ee" stroke-width="12" stroke-linecap="round"/><path d="M77 70h25" stroke="#ffae73" stroke-width="5"/>`;break;
default:d=`<circle cx="90" cy="60" r="32" fill="none" stroke="${c}" stroke-width="2"/><path d="M90 16v19m0 50v19M46 60h19m50 0h19" stroke="${c}" stroke-width="3"/><circle cx="90" cy="60" r="13" fill="#4c7b9e"/>`;
}return `<svg viewBox="0 0 180 125" role="img" aria-label="${esc(type)}"><circle cx="20" cy="20" r="1" fill="#86a7c3"/><circle cx="153" cy="102" r="1" fill="#86a7c3"/>${d}</svg>`}

export function hud(){return `<div class="hud">${Object.entries(LABELS).map(([k,n])=>{const v=game.state.r[k],limit=k==='money'?FLIGHT_BUDGET:100,low=!['money','science'].includes(k)&&v<25,warn=!['money','science'].includes(k)&&v<45;return `<div class="stat ${low?'danger':warn?'warn':''}"><span class="stat-label">${n}</span><b>${k==='energy'?'ϟ ':k==='life'?'◉ ':k==='comm'?'⌁ ':''}${v}<small> ${k==='money'?'M':k==='science'?'pts':'/100'}</small></b><div class="bar"><span style="width:${clamp(v/limit*100)}%;background:${k==='energy'?'#f5d36b':k==='life'?'#89e6bd':k==='hull'?'#ffae73':'#91dbff'}"></span></div></div>`}).join('')}</div>`}

export function prep(){game.screen='prep';ensureOffer();const req=requirements();$('#app').innerHTML=translateHtml(`<div class="section-top fade-in"><div><p class="eyebrow">01 / HANGAR DE ENSAMBLAJE</p><h2>Vamos a construir tu nave.</h2><p>Añade equipo para llenar tus reservas. Puedes probar y cambiar tu elección antes de despegar.</p></div><button id="homeBack" class="small">← Inicio</button></div>${hangarBrief()}${hud()}<div class="two-col"><section><div class="equip-grid">${MODULES.filter(m=>['capsule','battery','oxygen','antenna'].includes(m.id)).map((m,i)=>`<button class="equipment ${has(m.id)?'on':''}" data-module="${m.id}" aria-pressed="${has(m.id)}"><div class="top"><span>${m.type}</span><span>${has(m.id)?'✓ A BORDO':'＋ AÑADIR'}</span></div><h3>${m.name}</h3><div class="art">${art(m.icon,i)}</div><p>${m.desc}</p><div class="effect">${deltaText(m.gain)}${m.uses?`<br>${m.uses} usos de contingencia`:''}</div><div class="cost"><b>${m.cost} M</b><span>${m.mass} kg</span></div></button>`).join('')}</div><section id="extraEquipment" class="extra-equipment" ><h3>✦ Elige hasta 3 de los ${game.state.offer.length-4} extras de esta partida</h3><p class="mini">El almacén cambia al comenzar otra misión. Hay al menos una opción de energía, soporte, protección y ciencia.</p><div class="equip-grid mt">${game.state.offer.filter(id=>!CORE_MODULES.includes(id)).map(id=>MODULES.find(m=>m.id===id)).map((m,i)=>`<button class="equipment ${has(m.id)?'on':''}" data-module="${m.id}" aria-pressed="${has(m.id)}"><div class="top"><span>${m.type}</span><span>${has(m.id)?'✓ A BORDO':'＋ AÑADIR'}</span></div><h3>${m.name}</h3><div class="art">${art(m.icon,i)}</div><p>${m.desc}</p><div class="effect">${deltaText(m.gain)}${m.uses?`<br>${m.uses} usos de contingencia`:''}</div><div class="cost"><b>${m.cost} M</b><span>${m.mass} kg</span></div></button>`).join('')}</div></section></section><aside class="side"><div class="panel"><p class="eyebrow">TU NAVE / CONFIGURACIÓN ACTUAL</p>${launcherSummary()}<div class="hangar"><canvas id="scene"></canvas></div><div class="load-list">${game.state.load.length?MODULES.filter(m=>has(m.id)).map(m=>`<div><span>${m.name}</span><b class="green">✓</b></div>`).join(''):'<p>Añade módulos. La nave se actualizará con tu carga.</p>'}</div></div><div class="panel"><h3>Lista de lanzamiento</h3><div class="requirements">${req.map(r=>`<div class="${r.ok?'ok':'bad'}">${r.ok?'✓':'○'} ${r.text}</div>`).join('')}</div><button id="launch" class="primary" ${req.some(r=>!r.ok)?'disabled':''}>Iniciar lanzamiento ↗</button><p class="tagline">Sugerencia: una batería, oxígeno, antena y cápsula permiten despegar. Las reservas y herramientas hacen la diferencia más adelante.</p><button class="small mt" id="loadExample">Cargar configuración equilibrada</button></div></aside></div>`);document.querySelectorAll('[data-module]').forEach(b=>b.onclick=()=>toggle(b.dataset.module));$('#launch').onclick=launch;$('#homeBack').onclick=home;$('#loadExample').onclick=loadRecommended;learnDecorate();document.querySelectorAll('[data-specialty]').forEach(b=>b.onclick=()=>setSpecialty(b.dataset.specialty));document.querySelectorAll('[data-launcher]').forEach(b=>b.onclick=()=>setLauncher(b.dataset.launcher))}

export function album(){modal(`<p class="eyebrow">CUADERNO DE EXPLORACIÓN</p><h2>${game.state.discoveries.length} descubrimientos.</h2><p>Tu tripulación ha documentado estos temas durante la misión.</p>${game.state.discoveries.map(k=>fact(k)).join('')}${game.state.photos.length?'<h3 class="mt">Registro fotográfico</h3>':''}<div class="collection">${game.state.photos.map(p=>`<div class="panel"><img alt="Captura científica del simulador" src="${p.image}" style="width:100%;border-radius:8px"><p>${esc(p.name)} · encuadre ${p.quality}%</p></div>`).join('')}</div>`)}

export function cameraUI(){if(!activityRuntime.activity.targets.length)activityRuntime.activity.targets=Array.from({length:5},(_,i)=>({x:110+i*145,y:95+Math.random()*140,r:26+Math.random()*14,speed:(18+Math.random()*25)*(i%2?-1:1),seed:i+3,captured:false}));$('#activityContent').innerHTML=translateHtml('<canvas id="taskCanvas" width="900" height="340" aria-label="Visor de fotografía: toca los objetos en movimiento"></canvas><div class="readout" id="taskReadout"></div><div class="controls"><button id="takePhoto" class="primary">Fotografiar el centro · Espacio</button><button id="endTask">Cerrar sesión de observación</button><p>Ratón o dedo: toca el objeto. Teclado: flechas para mover la mira y Espacio para disparar. Dispones de 30 segundos de juego.</p></div>');$('#taskCanvas').onpointerdown=e=>{const c=e.currentTarget,b=c.getBoundingClientRect();activityRuntime.activity.pointer={x:(e.clientX-b.left)/b.width*900,y:(e.clientY-b.top)/b.height*340};shoot()};$('#taskCanvas').onpointermove=e=>{if(!activityRuntime.activity||activityRuntime.activity.done)return;const b=e.currentTarget.getBoundingClientRect();activityRuntime.activity.pointer={x:(e.clientX-b.left)/b.width*900,y:(e.clientY-b.top)/b.height*340}};$('#takePhoto').onclick=shoot;$('#endTask').onclick=()=>completeActivity({science:activityRuntime.activity.science,energy:-4},'bennu',`${activityRuntime.activity.hits} fotografías válidas de ${activityRuntime.activity.shots} exposiciones.`,activityRuntime.activity.hits>=3?2:0);updateCameraReadout()}

export function updateCameraReadout(){if($('#taskReadout'))$('#taskReadout').textContent=uiText(`TOMAS ${activityRuntime.activity.shots}/6 · HALLAZGOS ${activityRuntime.activity.hits}/3 · CIENCIA +${activityRuntime.activity.science} · ${has('camera')?'CÁMARA CIENTÍFICA ACTIVA':'CÁMARA BÁSICA DE NAVEGACIÓN'}`)}

export function signalUI(){activityRuntime.activity.attempts ||= 0;$('#activityContent').innerHTML=translateHtml('<canvas id="taskCanvas" width="900" height="270" aria-label="Ondas de señal de comunicaciones"></canvas><label>Azimut de apuntamiento <span id="azValue"></span><input id="az" type="range" min="0" max="100" value="20"></label><label>Sintonía de prueba <span id="frValue"></span><input id="fr" type="range" min="0" max="100" value="80"></label><div class="readout" id="taskReadout"></div><div class="controls"><button id="lockSignal" class="primary">Verificar enlace · 2 intentos</button><button id="endTask">Continuar con el enlace actual</button></div>');const upd=()=>{if(!activityRuntime.activity)return;const a=activityRuntime.activity.signal;a.az=+$('#az').value;a.fr=+$('#fr').value;$('#azValue').textContent=uiText(a.az+'°');$('#frValue').textContent=uiText(a.fr);const q=signalQuality();$('#taskReadout').textContent=uiText(`CALIDAD ${q}% · OBJETIVO ≥85% · ${has('relay')?'REPETIDOR: TOLERANCIA AMPLIADA':'BUSCA EL MÁXIMO MOVIENDO CADA CONTROL'}`)};$('#az').oninput=upd;$('#fr').oninput=upd;upd();$('#lockSignal').onclick=()=>{activityRuntime.activity.attempts++;const q=signalQuality();tone(q>=85?'correct':'error');if(q>=85||activityRuntime.activity.attempts>=2)completeActivity({comm:q>=85?18:-15,science:q>=85?12:2,energy:-5},'comm',`Enlace verificado al ${q}%.`,q>=85?2:-1);else{notify('✕ OBJETIVO NO ALCANZADO · Enlace débil. Ajusta los controles; queda un intento.');$('#lockSignal').textContent=uiText('Verificar enlace · 1 intento')}};$('#endTask').onclick=()=>completeActivity({comm:-10,science:2,energy:-3},'comm','La actividad se cerró antes de verificar un enlace estable.',0)}

export function canvasSetup(canvas){if(!canvas)return null;const rect=canvas.getBoundingClientRect(),ratio=Math.min(devicePixelRatio||1,2),w=rect.width||900,h=rect.height||340;if(canvas.width!==Math.round(w*ratio)||canvas.height!==Math.round(h*ratio)){canvas.width=Math.round(w*ratio);canvas.height=Math.round(h*ratio)}const c=canvas.getContext('2d');c.setTransform(ratio,0,0,ratio,0,0);return{c,w,h}}

export function ellipse(c,x,y,rx,ry,color){c.fillStyle=color;c.beginPath();c.ellipse(x,y,rx,ry,0,0,Math.PI*2);c.fill()}

export function starfield(c,w,h,t){c.fillStyle='#08111f';c.fillRect(0,0,w,h);for(let i=0;i<85;i++){const x=((Math.sin(i*127.1)*43758.5453)%1+1)%1*w,y=((Math.cos(i*311.7)*13245.421)%1+1)%1*h;const alpha=reduced?.6:.35+.35*Math.sin(t*.5+i);c.fillStyle=`rgba(196,222,248,${alpha})`;c.fillRect(x,y,i%8===0?2:1,i%8===0?2:1)}}

export function rock(c,x,y,r,seed,t=0){c.save();c.translate(x,y);c.rotate(t*.05+seed);c.fillStyle=['#86929c','#9f9e91','#858796','#677c8d'][seed%4];c.strokeStyle='#b4c0ca';c.lineWidth=1;c.beginPath();for(let j=0;j<10;j++){const a=j/10*Math.PI*2,rr=r*(.8+.16*Math.sin(seed+j*43));if(j===0)c.moveTo(Math.cos(a)*rr,Math.sin(a)*rr);else c.lineTo(Math.cos(a)*rr,Math.sin(a)*rr)}c.closePath();c.fill();c.stroke();ellipse(c,-r*.2,-r*.2,r*.17,r*.13,'#536577');ellipse(c,r*.3,r*.2,r*.22,r*.17,'#5b6b79');c.restore()}

export function moon(c,x,y,r,t){const g=c.createRadialGradient(x-r*.4,y-r*.4,0,x,y,r);g.addColorStop(0,'#e3ebef');g.addColorStop(.6,'#8999ac');g.addColorStop(1,'#2b3d56');ellipse(c,x,y,r,r,g);for(let i=0;i<17;i++){const a=i*2.4,rr=r*(.18+.64*((i*31%17)/17));ellipse(c,x+Math.cos(a)*rr,y+Math.sin(a)*rr,r*(.02+.05*(i%3)),r*(.015+.04*(i%3)),'#576b8266')}}

export function astronaut(c,x,y,size,t,dead=false){c.save();c.translate(x,y+(dead?0:Math.sin(t*1.4)*4));c.scale(size,size);if(dead)c.rotate(.45);c.fillStyle='#7b8ea4';c.fillRect(-24,-15,48,56);c.fillStyle='#d6e1e9';c.beginPath();c.roundRect(-19,-9,38,48,9);c.fill();ellipse(c,0,-24,25,25,'#dce7ed');ellipse(c,0,-25,19,13,dead?'#071421':'#174e6f');ellipse(c,-6,-29,7,3,dead?'#19212c':'#85d3ee');c.strokeStyle='#dce7ed';c.lineWidth=13;c.lineCap='round';c.beginPath();c.moveTo(-18,1);c.lineTo(-31,24+Math.sin(t)*3);c.moveTo(18,1);c.lineTo(30,18-Math.sin(t)*4);c.moveTo(-10,36);c.lineTo(-14,62);c.moveTo(10,36);c.lineTo(15,62);c.stroke();c.fillStyle='#ffae73';c.fillRect(-18,8,36,7);c.fillStyle='#223f56';c.fillRect(-10,-1,20,8);c.restore()}

export function ship(c,x,y,s,t,mode='orbit'){c.save();c.translate(x,y);c.scale(s,s);if(mode==='orbit')c.rotate(-.4);if(hasSafe('solar')){c.fillStyle='#184970';c.strokeStyle='#85cdef';for(const side of[-1,1]){c.fillRect(side<0?-132:40,-15,92,40);c.strokeRect(side<0?-132:40,-15,92,40);for(let j=1;j<5;j++){const xx=(side<0?-132:40)+j*18;c.beginPath();c.moveTo(xx,-15);c.lineTo(xx,25);c.stroke()}}}c.fillStyle='#d5e2ec';c.beginPath();c.moveTo(-35,55);c.lineTo(-35,-22);c.lineTo(0,-68);c.lineTo(35,-22);c.lineTo(35,55);c.closePath();c.fill();c.fillStyle='#254965';c.fillRect(-17,-22,34,23);c.fillStyle='#ffae73';c.fillRect(-35,22,70,11);if(hasSafe('antenna')){c.strokeStyle='#b0cfdf';c.lineWidth=3;c.beginPath();c.moveTo(20,-40);c.lineTo(57,-65);c.stroke();ellipse(c,58,-67,12,6,'#b4cddc')}if(mode==='launch'||mode==='landing'){const flicker=reduced?1:1+.2*Math.sin(t*30);c.fillStyle='#ffa25f';c.beginPath();c.moveTo(-23,58);c.lineTo(0,58+65*flicker);c.lineTo(23,58);c.fill();c.fillStyle='#ffe2a3';c.beginPath();c.moveTo(-12,58);c.lineTo(0,58+40*flicker);c.lineTo(12,58);c.fill()}c.restore()}

export function hasSafe(id){return game.state?has(id):true}

export function sceneDraw(canvas,t,mode){const ctx=canvasSetup(canvas);if(!ctx)return;const{c,w,h}=ctx;starfield(c,w,h,t);if(mode==='home'){moon(c,w*.67,h*.46,Math.min(w,h)*.31,t);c.strokeStyle='#435971';c.beginPath();c.ellipse(w*.62,h*.48,w*.36,h*.35,-.4,0,Math.PI*2);c.stroke();ship(c,w*.27,h*.44,.68,t);astronaut(c,w*.62,h*.7,.8,t);return}if(mode==='prep'){c.fillStyle='#152b3d';c.fillRect(0,h-22,w,22);drawLaunchPreview(c,w,h,t);return}const p=game.state?phase():1;if(p===0||mode==='launch'){const g=c.createLinearGradient(0,h/2,0,h);g.addColorStop(0,'#1c3f68');g.addColorStop(1,'#5093c0');c.fillStyle=g;c.fillRect(0,h/2,w,h/2);for(let i=0;i<6;i++)ellipse(c,(i*160+t*12)%w,h*.77+Math.sin(i)*20,110,24,'#b5d2e740');ship(c,w*.55,h*.43,.95,t,'launch');astronaut(c,w*.16,h*.57,.75,t)}else if(p===1){ellipse(c,w*.12,h*.72,70,70,'#24638b');ellipse(c,w*.1,h*.72,42,35,'#478674');moon(c,w*.85,h*.3,45,t);ship(c,w*.58,h*.45,.8,t);astronaut(c,w*.28,h*.5,.8,t)}else{moon(c,w*.86,-45,110,t);c.fillStyle='#394b60';c.beginPath();c.moveTo(0,h);for(let x=0;x<=w;x+=30)c.lineTo(x,h*.8+Math.sin(x*.025)*12);c.lineTo(w,h);c.fill();for(let i=0;i<8;i++)rock(c,i*w/8,h*.88+Math.sin(i)*8,9+i%3*5,i,t);if(p===3){c.fillStyle='#b9cbd7';c.beginPath();c.ellipse(w*.4,h*.8,80,63,0,Math.PI,0);c.fill();c.fillStyle='#223e56';c.fillRect(w*.39,h*.68,25,40)}else ship(c,w*.65,h*.5,.7,t,'landing');astronaut(c,w*.22,h*.65,.9,t,game.state?.ending?.kind==='fatal')}
if(game.state?.r.energy<25){c.fillStyle='#cf4c6620';c.fillRect(0,0,w,h)} }

export function endCinema(){if(!game.cinema)return;stopCinemaSound();const cb=game.cinema.callback;game.cinema=null;$('#cinema').classList.add('hidden');cb()}

export function cinemaDraw(t){const{c,w,h}=canvasSetup($('#cinemaCanvas')),a=game.cinema,progress=Math.min(1,a.t/a.duration);starfield(c,w,h,t);const x=w*.5,y=h*.38,s=Math.min(1.8,w/450);c.save();if(a.type==='success'){c.restore();drawVictory($('#cinemaCanvas'),t);return}if(a.type==='damage'&&!reduced)c.translate(Math.sin(t*75)*5,Math.cos(t*60)*5);if(['launch','landing'].includes(a.type)){moon(c,w*.85,h*.5,110,t);ship(c,x,y+(a.type==='launch'?-progress*90:progress*60),s,t,a.type)}else if(a.type==='death'){astronaut(c,x,y,s,t,true);c.fillStyle=`rgba(1,5,12,${progress*.9})`;c.fillRect(0,0,w,h);c.strokeStyle='#f77d94';c.lineWidth=2;c.beginPath();c.moveTo(w*.2,h*.58);for(let xx=w*.2;xx<w*.8;xx+=4)c.lineTo(xx,h*.58+(progress<.6?Math.sin(xx*.4)*18*(1-progress):0));c.stroke()}else if(a.type==='damage'){ship(c,x,y,s,t);for(let i=0;i<22;i++){const ang=i*1.71;c.fillStyle='#ffae73';c.fillRect(x+Math.cos(ang)*progress*230,y+Math.sin(ang)*progress*170,3,3)}c.fillStyle=`rgba(240,60,80,${.08+.07*Math.sin(t*5)})`;c.fillRect(0,0,w,h)}else if(a.type==='camera'){rock(c,x,y,75,4,t);c.strokeStyle='#89e6bd';c.strokeRect(x-120,y-100,240,200);if(progress<.18){c.fillStyle='#ffffff66';c.fillRect(0,0,w,h)}}else if(['signal','antenna'].includes(a.type)){ship(c,x,y,s,t);for(let i=0;i<4;i++){c.strokeStyle=`rgba(145,219,255,${1-(progress+i*.25)%1})`;c.beginPath();c.arc(x,y,40+((progress+i*.25)%1)*250,-1.2,.5);c.stroke()}}else if(['water','oxygen','recycle'].includes(a.type)){astronaut(c,x,y,s,t);for(let i=0;i<35;i++)ellipse(c,x-140+i*8,y+Math.sin(i+t*3)*60,3,3,'#89e6bd88')}else{astronaut(c,x,y,s,t);c.strokeStyle='#89e6bd';c.beginPath();c.arc(x,y,140,0,Math.PI*2*progress);c.stroke()}c.restore()}

export function taskDraw(dt,t){if(!activityRuntime.activity||!$('#taskCanvas'))return;const a=activityRuntime.activity,canvas=$('#taskCanvas'),c=canvas.getContext('2d'),w=canvas.width,h=canvas.height;starfield(c,w,h,t);if(a.type==='camera'){for(const target of a.targets){if(!a.done&&!reduced){target.x+=target.speed*dt;if(target.x>860||target.x<40)target.speed*=-1}if(!target.captured)rock(c,target.x,target.y,target.r,target.seed,t);else{c.strokeStyle='#89e6bd';c.strokeRect(target.x-35,target.y-35,70,70)}}const p=a.pointer,r=has('camera')?42:28;c.strokeStyle='#a9eaff';c.lineWidth=2;c.strokeRect(p.x-r,p.y-r,r*2,r*2);c.beginPath();c.moveTo(p.x-7,p.y);c.lineTo(p.x+7,p.y);c.moveTo(p.x,p.y-7);c.lineTo(p.x,p.y+7);c.stroke();if(a.flash>0){c.fillStyle=`rgba(255,255,255,${a.flash*3})`;c.fillRect(0,0,w,h);a.flash-=dt}}else if(a.type==='signal'){const q=signalQuality();c.strokeStyle='#91dbff';c.lineWidth=2;c.beginPath();for(let x=0;x<w;x++){const y=h/2+Math.sin(x*.035+t*2)*35+Math.sin(x*.14+t*5)*(100-q)*.5;if(!x)c.moveTo(x,y);else c.lineTo(x,y)}c.stroke();c.fillStyle='#89e6bd';c.font='25px monospace';c.fillText(uiText(`ENLACE ${q}%`),35,45)}else if(a.type==='landing'){drawLanding(c,w,h,dt,t)}}

export function help(){modal(`<p class="eyebrow">TU PRIMER VIAJE</p><h2>Aprende una cosa a la vez.</h2><div class="help-steps"><div><span>1</span><h3>Prepara tu nave</h3><p>Elige «Mi primera nave» y mira cómo se llenan las reservas. Puedes cambiar el equipo después.</p></div><div><span>2</span><h3>Lee, imagina y decide</h3><p>En cada evento elige una acción. Las consecuencias aparecen después de decidir. La teoría NASA se puede consultar antes o leer al ver el resultado.</p></div><div><span>3</span><h3>Cuida tus reservas</h3><p>Usa baterías, tanques o reparaciones antes de que un sistema llegue a cero. Los objetos se agotan.</p></div><div><span>4</span><h3>Explora y aprende</h3><p>Cada viaje elige 7 minijuegos distintos de 11. Lee las instrucciones antes de iniciar su reloj; las explicaciones pausan el tiempo.</p></div></div><section class="glossary"><h3>¿Qué significa cada recurso?</h3><p><b>Créditos:</b> dinero para equipo y operación.<br><b>Energía:</b> electricidad para los sistemas.<br><b>Soporte vital:</b> reservas y sistemas que te mantienen con vida.<br><b>Comunicaciones:</b> calidad del enlace con la Tierra.<br><b>Integridad:</b> estado físico de la nave.<br><b>Propelente:</b> combustible para las maniobras.<br><b>Ciencia:</b> hallazgos que documentas.</p></section><p class="mini mt">Todo se juega con ratón, pantalla táctil o teclado. Las actividades pueden cerrarse sin acertar todo. Se conservan sus consecuencias.</p>`)}

export function learnDecorate(){if(!game.state||game.screen==='home'||game.screen==='report')return;const guide=$('#firstLoad');if(guide)guide.onclick=loadRecommended;if($('#learnHelp'))$('#learnHelp').onclick=help}

export function repairUI(){activityRuntime.activity.connections ||= {};activityRuntime.activity.selected=null;activityRuntime.activity.mistakes ||= 0;const pairs=[{id:'power',name:'Batería',icon:'ϟ',target:'Energía eléctrica',tip:'La batería almacena electricidad para los equipos.'},{id:'oxygen',name:'Tanque de oxígeno',icon:'O₂',target:'Aire para respirar',tip:'El oxígeno sostiene la respiración de la tripulación.'},{id:'filter',name:'Filtro de CO₂',icon:'◌',target:'Retirar el gas exhalado',tip:'Un filtro elimina CO₂. Añadir oxígeno no sustituye esta función.'}];activityRuntime.activity.pairs=pairs;const right=shuffle(pairs);$('#activityContent').innerHTML=translateHtml(`<div class="task-hero"><div class="art">${art('tools',1)}</div><div><span class="pill">SIN PRISA · 3 CONEXIONES</span><h3>Vuelve a conectar los sistemas</h3><p>Elige un equipo a la izquierda y su función a la derecha. Los símbolos y los nombres te ayudan.</p></div></div><div class="connection-board"><div>${pairs.map(p=>`<button data-plug="${p.id}"><span>${p.icon}</span>${p.name}</button>`).join('')}</div><div>${right.map(p=>`<button data-socket="${p.id}">${p.target}</button>`).join('')}</div></div><p id="repairHint" class="task-hint" role="status">Empieza seleccionando una pieza de equipo.</p><div class="controls"><button id="finishRepair" class="primary" disabled>Guardar reparación →</button><button id="leaveRepair">Continuar sin completar</button></div>`);document.querySelectorAll('[data-plug]').forEach(b=>b.onclick=()=>{if(activityRuntime.activity.connections[b.dataset.plug])return;activityRuntime.activity.selected=b.dataset.plug;document.querySelectorAll('[data-plug]').forEach(x=>x.classList.toggle('selected',x===b));$('#repairHint').textContent=uiText(pairs.find(p=>p.id===activityRuntime.activity.selected).tip)});document.querySelectorAll('[data-socket]').forEach(b=>b.onclick=()=>connectRepair(b.dataset.socket));$('#finishRepair').onclick=()=>finishRepair();$('#leaveRepair').onclick=()=>finishRepair()}

export function solarUI(){activityRuntime.activity.angle ??= 10;activityRuntime.activity.sunAngle ??= 45+Math.floor(Math.random()*60);$('#activityContent').innerHTML=translateHtml(`<div class="solar-stage"><div class="solar-sun">☀</div><div class="sun-rays"></div><div id="solarPanel"><span></span><span></span><span></span><span></span><span></span><span></span></div><div class="solar-ground"></div></div><h3 class="mt">Busca la mejor orientación</h3><p>Gira el panel hasta obtener al menos 90% de captación. Mira cómo cambia el medidor.</p><label>Ángulo del panel · <strong id="angleText">10°</strong><input id="panelAngle" type="range" min="0" max="180" value="10"></label><div class="solar-meter"><span id="solarFill"></span></div><p id="solarReadout" class="task-hint" role="status"></p><div class="controls"><button id="collectSolar" class="primary">Recoger energía →</button><button id="solarHint" class="small">Dame una pista</button></div><p class="mini mt">La captación es un modelo simplificado. Con paneles a bordo recargas tu nave; sin ellos, usas un panel de entrenamiento y obtienes ciencia.</p>`);$('#panelAngle').oninput=()=>{activityRuntime.activity.angle=+$('#panelAngle').value;updateSolar()};$('#solarHint').onclick=()=>notify(`Busca un ángulo cercano a ${Math.round(activityRuntime.activity.sunAngle/10)*10}°. El máximo depende de la dirección del Sol.`);$('#collectSolar').onclick=finishSolar;updateSolar()}

export function updateSolar(){const q=solarYield();$('#solarPanel').style.transform=`translate(-50%,-50%) rotate(${activityRuntime.activity.angle-90}deg)`;$('#angleText').textContent=uiText(activityRuntime.activity.angle+'°');$('#solarFill').style.width=q+'%';$('#solarReadout').textContent=uiText(`Captación ${q}% · ${q>=90?'¡Buena orientación!':q>=50?'Puedes mejorar el ángulo.':'Llega poca luz al panel.'}`)}

export function launchTaskHint(){const helpButton=document.createElement('button');helpButton.id='learnTopHelp';helpButton.className='small';helpButton.textContent=uiText('¿Cómo se juega?');helpButton.onclick=help;document.querySelector('.header-actions').prepend(helpButton)}

export function drawFailure(canvas,t){const setup=canvasSetup(canvas);if(!setup)return;const{c,w,h}=setup;starfield(c,w,h,t);const kind=game.state.ending.scene||(game.state.r.hull<=0?'wreck':'drift');moon(c,w*.86,h*.23,Math.min(65,w*.11),t);if(kind==='wreck'){c.save();c.translate(w*.49,h*.42);c.rotate(-.5+Math.sin(t*.25)*.025);ship(c,0,0,Math.min(1.1,w/600),t,'hangar');for(let i=0;i<28;i++){const age=(t*.3+i/28)%1,x=18+age*165,y=15+Math.sin(i*17)*age*90;c.globalAlpha=(1-age)*.8;ellipse(c,x,y,12*(1-age)+2,6*(1-age)+2,i%2?'#ffb56b':'#e75b6f')}c.globalAlpha=1;c.restore();for(let i=0;i<8;i++)rock(c,w*(.16+i*.09)+Math.sin(t*.2+i)*8,h*(.58+Math.sin(i*3)*.12),4+i%3,i,t)}else{c.save();c.translate(w*.49+Math.sin(t*.25)*15,h*.45+Math.cos(t*.2)*9);c.rotate(-.35+Math.sin(t*.18)*.12);astronaut(c,0,0,Math.min(1.4,w/400),0,true);c.restore();c.globalAlpha=.3;ship(c,w*.18,h*.4,.38,t);c.globalAlpha=1}const shade=c.createLinearGradient(0,h*.5,0,h);shade.addColorStop(0,'#08101c00');shade.addColorStop(1,'#08101cee');c.fillStyle=shade;c.fillRect(0,0,w,h)}

export function ambientSpace(c,w,h,t){starfield(c,w,h,t);for(const [x,y,r,color]of[[.16,.24,.5,'rgba(97,71,160,.18)'],[.85,.7,.48,'rgba(44,108,139,.15)'],[.7,.12,.3,'rgba(87,110,170,.12)']]){const g=c.createRadialGradient(w*x,h*y,0,w*x,h*y,Math.max(w,h)*r);g.addColorStop(0,color);g.addColorStop(1,'rgba(8,17,31,0)');c.fillStyle=g;c.fillRect(0,0,w,h)}c.save();c.strokeStyle='#8fa6db17';c.lineWidth=1;c.beginPath();c.ellipse(w*.82,h*.72,w*.36,h*.24,-.4,0,Math.PI*2);c.stroke();c.globalAlpha=.12;moon(c,w*.94,h*.85,Math.min(w,h)*.19,t);c.restore()}

export function verdict(q){return q>=2?{icon:'✓',label:'ACIERTO',tone:'good',tip:'Tu acción cumple el objetivo de esta situación.'}:q===1?{icon:'✓',label:'ACIERTO CON COSTE EXTRA',tone:'good',tip:'Resuelves el problema, aunque consumes más recursos.'}:q===0?{icon:'!',label:'RESULTADO PARCIAL',tone:'mixed',tip:'Hay un beneficio, pero también un objetivo pendiente.'}:{icon:'✕',label:'ERROR',tone:'bad',tip:'La acción no resuelve la situación o empeora el problema.'}}

export function verdictHtml(q){const v=verdict(q);return `<div class="verdict ${v.tone}" role="status"><span aria-hidden="true">${v.icon}</span><div><strong>${v.label}</strong><p>${v.tip}</p></div></div>`}

export function outcomeDeltas(delta){return `<div class="deltas" aria-label="Cambios en tus recursos">${Object.entries(delta).filter(([,v])=>v).map(([k,v])=>`<span class="delta ${v<0?'negative':'positive'}">${v>0?'+':''}${v} ${LABELS[k]}</span>`).join('')}</div>`}

export function fact(key){const s=SOURCES[key];return `<div class="fact"><b>DATO NASA · PARA APRENDER</b><p lang="es">${esc(QUICK_FACTS[key]||s.fact)}</p><a class="source" href="${s.url}" target="_blank" rel="noopener">${esc(s.title)} ↗</a></div>`}

export function progressInfo(){if(!game.state||game.screen==='home')return null;const decisions=Math.min(12,game.state.turn+(game.state.feedback?1:0)),tasks=new Set(game.state.miniDone||[]).size,total=12+Object.keys(taskPlan()).length;return{decisions,tasks,total,done:decisions+tasks,percent:Math.round((decisions+tasks)/total*100)}}

export function syncProgress(){const el=$('#journeyProgress'),p=progressInfo();if(!el)return;if(!p){el.hidden=true;syncProgress.last='';return}el.hidden=false;const signature=[p.done,game.state.stage,game.state.ending?.kind,game.screen].join(':');if(signature===syncProgress.last)return;syncProgress.last=signature;el.innerHTML=translateHtml(`<div class="journey-copy"><strong>${game.state.ending?'RECORRIDO FINAL':game.state.stage==='prep'?'PREPARA TU VIAJE':'TU RECORRIDO'} · ${p.percent}%</strong><span>${p.decisions}/12 decisiones · ${p.tasks}/${Object.keys(taskPlan()).length} minijuegos</span></div><div class="journey-track" role="progressbar" aria-label="Recorrido completado; no indica probabilidad de ganar" aria-valuemin="0" aria-valuemax="${p.total}" aria-valuenow="${p.done}" aria-valuetext="${p.percent}% del recorrido"><span style="width:${p.percent}%"></span></div><small>${game.state.ending?'Revisa el resultado de tu misión.':game.state.stage==='prep'?'Despega para comenzar.':'Avanzar no garantiza ganar: cuida las reservas y reúne 65 puntos de ciencia.'}</small>`)}

export function renderActivityView(resumed){const type=activityRuntime.activity.type,cfg=ACTIVITY_CONFIG[type];$('#app').innerHTML=translateHtml(`<div class="section-top"><div><p class="eyebrow">MINIJUEGO · ${Object.values(taskPlan()).indexOf(type)+1} DE ${Object.keys(taskPlan()).length}</p><h2>${cfg.title}</h2>${game.state.demo?'<span class="pill">DEMO · 1 alunizaje + 4 casos</span>':''}</div>${specialtyBadge()}</div>${hud()}<section class="panel activity" id="challengePanel" tabindex="-1" aria-label="${esc(cfg.title)}"><div class="challenge-clock"><div><span class="eyebrow">TIEMPO DE JUEGO</span><strong id="activityTimer" role="timer" aria-live="off">${Math.ceil(activityRuntime.activity.remaining)} s</strong></div><span id="clockStatus">Preparado · el reloj aún no corre</span><div class="clock-track"><span id="activityTimeFill" style="width:${activityRuntime.activity.remaining/cfg.seconds*100}%"></span></div></div><p>${esc(cfg.desc)}</p><div id="activityContent"><div class="challenge-brief"><div class="art">${art(({rover:'rover',spectra:'scan',transit:'orbit',powergrid:'battery',repair:'tools',camera:'camera',landing:'ship',solar:'solar',signal:'signal',survey:'moon',meteor:'moon'})[type],game.state.turn)}</div><h3>${cfg.goal}</h3><p>El contador empieza al pulsar el botón. Se pausa al leer una respuesta o al ocultar esta pestaña.</p>${resumed?'<p>Retomas el mismo reto y el tiempo que te quedaba.</p>':''}<button id="startChallenge" class="primary continue-button">${resumed?'Reanudar':'Iniciar'} reto · ${Math.ceil(activityRuntime.activity.remaining)} s →</button></div></div></section>${fact(cfg.source)}`);$('#startChallenge').onclick=()=>startChallenge();save();syncProgress();focusActivity()}

export function transitUI(){const a=activityRuntime.activity;a.transit ||= {target:[2.25,4,6.25,9][Math.floor(Math.random()*4)],radius:10};const tr=a.transit;$('#activityContent').innerHTML=translateHtml(`<div class="transit-stage"><div class="transit-star"></div><div id="transitPlanet"></div></div><h3>Reproduce una caída de brillo del ${tr.target}%</h3><p>La estrella mantiene su tamaño. Ajusta el radio relativo del planeta.</p><label>Radio del planeta / radio estelar: <strong id="transitRadius"></strong><input id="transitSlider" aria-label="Radio del planeta en porcentaje del radio estelar" type="range" min="5" max="35" step="1" value="${tr.radius}"></label><div id="transitGraph"></div><p id="transitReadout" class="task-hint"></p><div class="controls"><button id="verifyTransit" class="primary">Verificar modelo</button><button id="leaveNewTask" class="primary continue-button">Continuar con el modelo actual →</button></div><p class="mini">Tránsito central idealizado: caída = (radio del planeta / radio estelar)². No incluye ruido, atmósferas ni oscurecimiento del borde estelar. No es el análisis de una estrella real.</p>`);$('#transitSlider').oninput=()=>{a.transit.radius=+$('#transitSlider').value;updateTransit();save()};$('#verifyTransit').onclick=finishTransit;$('#leaveNewTask').onclick=finishTransit;updateTransit()}

export function updateTransit(){const tr=activityRuntime.activity.transit,depth=tr.radius*tr.radius/100;$('#transitPlanet').style.width=tr.radius*2+'px';$('#transitPlanet').style.height=tr.radius*2+'px';$('#transitRadius').textContent=uiText(tr.radius+'%');$('#transitReadout').textContent=uiText(`Tu caída: ${depth.toFixed(2)}% · Objetivo: ${tr.target}% · Tolerancia: ±0,30 puntos porcentuales`);const curve=d=>`M10 18H100L135 ${18+d*6}H225L260 18H350`;$('#transitGraph').innerHTML=translateHtml(`<svg viewBox="0 0 360 110" role="img" aria-label="Compara caída objetivo y caída de tu modelo"><path d="${curve(tr.target)}" fill="none" stroke="#dfc8ff" stroke-width="7" opacity=".5"/><path d="${curve(depth)}" fill="none" stroke="#8be8c3" stroke-width="3"/><text x="10" y="103" fill="#deebff" font-size="11">Violeta: objetivo · Verde: tu modelo · Tiempo →</text></svg>`)}

export function powergridUI(){const a=activityRuntime.activity;a.gridRounds ||= shuffle([{label:'Preparar una observación',mins:[4,2,3],budget:10},{label:'Recuperar el enlace',mins:[4,4,1],budget:10},{label:'Proteger la cabina',mins:[6,2,1],budget:10}]);a.allocation ||= [0,0,0];const d=a.gridRounds[a.round];$('#activityContent').innerHTML=translateHtml(`<p class="eyebrow">DISTRIBUCIÓN · SITUACIÓN ${a.round+1}/3</p><h3>${d.label}</h3><p>Disponibles: <b>${d.budget} unidades de potencia del reto.</b> A cada sistema dale al menos su mínimo. El total no puede superar ${d.budget}.</p><div class="power-bus">${['Soporte vital','Comunicaciones','Ciencia'].map((name,i)=>`<label><b>${name}</b><span>Mínimo ${d.mins[i]} · Asignado <strong id="allocation${i}">${a.allocation[i]}</strong></span><input data-allocation="${i}" type="range" min="0" max="8" step="1" value="${a.allocation[i]}" aria-label="Potencia para ${name}"></label>`).join('')}</div><p id="gridReadout" class="task-hint"></p><button id="checkGrid" data-grid-check class="primary">Aplicar distribución</button><div id="newTaskFeedback" aria-live="polite"></div><p class="mini">Las cifras son un rompecabezas educativo de presupuesto, no especificaciones de una nave.</p>`);document.querySelectorAll('[data-allocation]').forEach(b=>b.oninput=()=>{a.allocation[+b.dataset.allocation]=+b.value;updatePowergrid();save()});$('#checkGrid').onclick=checkPowergrid;updatePowergrid()}

export function updatePowergrid(){const a=activityRuntime.activity,d=a.gridRounds[a.round],total=a.allocation.reduce((s,n)=>s+n,0);for(let i=0;i<3;i++)$('#allocation'+i).textContent=uiText(a.allocation[i]);$('#gridReadout').textContent=uiText(`Total ${total}/${d.budget} · ${total>d.budget?'! SOBRECARGA':d.mins.every((m,i)=>a.allocation[i]>=m)?'✓ Mínimos cubiertos':'Faltan mínimos: revisa los tres sistemas.'}`)}

export function surveyUI(){const a=activityRuntime.activity;a.atlasOrder ||= shuffle([0,1,2]);const d=ATLAS[a.atlasOrder[a.round]];$('#activityContent').innerHTML=translateHtml(`<div class="art mt" style="height:200px">${art(d.icon,a.round)}</div><p class="eyebrow mt">CUERPO ${a.round+1}/3 · ${d.name}</p>${fact(d.key)}<h3 class="mt">${d.q}</h3><div class="inventory mt">${shuffle(d.answers.map((text,i)=>({text,i}))).map(({text,i})=>`<button data-answer="${i}">${esc(text)}</button>`).join('')}</div><div id="newTaskFeedback" aria-live="polite"></div>`);document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>answerSurvey(+b.dataset.answer));if(a.locked&&a.review)renderRoundReview()}

export function meteorUI(){const a=activityRuntime.activity;a.cases ||= shuffle(METEOR_CASES);const d=a.cases[a.round];$('#activityContent').innerHTML=translateHtml(`<p class="eyebrow">DETECTIVE DE METEOROS · ESCENA ${a.round+1}/3</p><div class="meteor-stage ${d.scene}" role="img" aria-label="${esc(d.label)}"><span class="meteor-world"></span><span class="meteor-stone"></span><span class="meteor-scene-label">${d.scene==='space'?'EN EL ESPACIO':d.scene==='sky'?'EN LA ATMÓSFERA TERRESTRE':'EN EL SUELO TERRESTRE'}</span></div><h3 class="mt">${d.label}</h3><p>¿Cómo se llama lo que estamos observando?</p>${fact('meteors')}<div class="meteor-answers">${shuffle(['meteoroide','meteoro','meteorito']).map(k=>`<button data-meteor="${k}">${k[0].toUpperCase()+k.slice(1)}</button>`).join('')}</div><div id="newTaskFeedback" aria-live="polite"></div><p class="mini">Escenas ilustradas de la Tierra, fuera de la ruta lunar de la misión.</p>`);document.querySelectorAll('[data-meteor]').forEach(b=>b.onclick=()=>answerMeteor(b.dataset.meteor));if(a.locked&&a.review)renderRoundReview()}

export function renderRoundReview(){const a=activityRuntime.activity;if(!a?.review)return;document.querySelectorAll('[data-answer],[data-meteor],[data-spectrum],[data-allocation],[data-grid-check]').forEach(b=>b.disabled=true);$('#newTaskFeedback').innerHTML=translateHtml(`${verdictHtml(a.review.ok?2:-1)}<p>${esc(a.review.why)}</p><p class="mini">⏸ Reloj en pausa mientras lees.</p><button id="nextNewRound" class="primary continue-button">Continuar · ${a.round===2?'ver resultado':'siguiente ronda'} →</button>`);$('#nextNewRound').onclick=advanceActivityRound}

export function goalsHtml(){return `<div class="mission-goals"><h3>Tu meta, desde el despegue</h3>${missionCriteria().slice(1,5).map(([name,ok,value])=>`<div><span>${ok?'✓':'○'} ${name}</span><strong>${value}</strong></div>`).join('')}<p>Completa 12 casos, fundamenta al menos 8 decisiones y reúne estas reservas. Lee las pistas y conserva la nave para volver.</p></div>`}

export function flightForecast(){const events=game.state.pools.flat(),count=keys=>events.filter(e=>keys.includes(e.source)).length,items=[['Potencia y entorno',count(['power','south','thermal'])],['Aire y agua',count(['life','water'])],['Enlace y maniobras',count(['comm','terrain','gravity'])],['Muestras y mantenimiento',count(['ice','drill','dust','engineering'])]];return `<div class="flight-forecast"><h3>Lo que prevé esta ruta</h3><div>${items.map(([name,n])=>`<span>${name}<b>${n} casos</b></span>`).join('')}</div><p>Usa esta previsión para elegir los tres extras. Más reservas, protección y mejores instrumentos resuelven necesidades diferentes. Todos los viajes incluyen equipo básico de supervivencia.</p></div>`}

export function mission(){if(game.state.activityResult&&!game.state.ending){renderActivityResult();return}if(game.state.ending){report();return}game.screen='mission';const e=event();$('#app').innerHTML=translateHtml(`<div class="section-top"><div><p class="eyebrow">CONTROL DE MISIÓN · AM-${String(game.state.turn+1).padStart(2,'0')}</p><h2>${PHASES[phase()]}</h2></div><button id="abort" class="small">Regresar antes de tiempo</button></div>${hud()}<nav class="phase-strip">${PHASES.map((n,i)=>`<div class="phase-step ${phase()===i?'active':i<phase()?'done':''}">${String(i+1).padStart(2,'0')} / ${n}</div>`).join('')}</nav><div class="two-col"><section><div class="panel mission-scene"><canvas id="scene"></canvas><div class="scene-overlay"><span class="pill">${e.shadow?'ZONA EN SOMBRA':'CONTROL DE NAVE EN VIVO'}</span><span class="pill">DECISIÓN ${game.state.turn+1} / 12</span><div class="status"><b>ASTRONAUTA / ESTADO</b>${game.state.r.life<25?'Soporte bajo. Revisa tus reservas antes de actuar.':game.state.r.energy<25?'Potencia baja. Comprueba batería y consumos.':game.state.r.hull<35?'Hay daños: las reparaciones pueden conservar el vehículo.':'Sistemas operativos. Lee el caso y relaciona sus pistas.'}</div></div></div>${game.state.feedback?feedbackHtml():`${caseBrief(e)}<div class="choice-heading"><h3>¿Qué harías?</h3><p>Las acciones responden a este contexto. El equipo que llevas también puede influir.</p></div><div class="choices">${e.options.map((o,i)=>`<article class="choice-wrap"><button class="choice" data-option="${i}" ${o.needs&&!has(o.needs)?'disabled':''}><div class="art">${art(o.icon,i)}</div><span class="letter">OPCIÓN ${String.fromCharCode(65+i)}</span><h3>${esc(o.title)}</h3><p>${esc(o.desc)}</p>${o.needs&&!has(o.needs)?'<span class="equipment-needed">Requiere equipo de muestreo a bordo</span>':''}</button></article>`).join('')}</div>`}</section>${sidebar()}</div>`);bindMission();if(game.state.feedback){$('#continue').onclick=next;focusResult()}else window.scrollTo({top:0,behavior:reduced?'instant':'smooth'});save();syncProgress();syncContinueDock()}

export function sidebar(){return `<aside class="side"><div class="panel"><p class="eyebrow">TU ESPECIALIDAD</p><div class="specialty-heading">${specialtyBadge()}</div>${goalsHtml()}<button class="small mt" id="album">Cuaderno · ${game.state.discoveries.length} temas</button></div><div class="panel"><h3>Tu equipo en uso</h3><p class="mini">Antes de decidir puedes activar una carga. Batería y oxígeno de respaldo se conectan si evitan el agotamiento.</p><div class="inventory mt">${MODULES.filter(m=>has(m.id)&&m.uses).map(m=>`<button data-use="${m.id}" ${game.state.uses[m.id]<=0||game.state.feedback?'disabled':''}><span class="uses">${game.state.uses[m.id]}/${m.uses}</span><strong>${m.name}</strong><small>${m.actionText}</small></button>`).join('')}</div>${game.state.shield?'<p class="mini green mt">✓ Protección preparada para el próximo caso.</p>':''}</div><section class="panel flight-log"><h3>Últimas decisiones</h3>${game.state.history.slice(-3).reverse().map(h=>`<div class="journal-entry" lang="es"><b>${esc(h.title)}</b><small>${esc(h.summary)}</small></div>`).join('')||'<p class="mini">Tu registro comienza con la primera decisión.</p>'}</section></aside>`}

export function focusResult(){const target=$('#resultPanel');target?.focus?.({preventScroll:true});target?.scrollIntoView?.({block:'start',behavior:reduced?'instant':'smooth'})}

export function syncContinueDock(){const el=$('#continueDock');if(!el)return;const ready=!!game.state&&!game.state.ending&&!game.cinema&&((game.screen==='mission'&&game.state.feedback)||(game.screen==='activityResult'&&game.state.activityResult));el.hidden=!ready;document.body?.classList.toggle('has-continue',!!ready);if(ready){const progress=$('#journeyProgress');el.style.bottom=((progress&&!progress.hidden?progress.getBoundingClientRect().height:0)+12)+'px'}if(!ready){syncContinueDock.last='';return}const type=game.screen==='activityResult'?'activity':'decision';if(syncContinueDock.last===type)return;syncContinueDock.last=type;el.innerHTML=translateHtml(`<div><span>Resultado registrado</span><button id="dockContinue" class="primary continue-button">Continuar →</button></div>`);$('#dockContinue').onclick=()=>{el.hidden=true;if(type==='activity')continueActivityResult();else next()}}

export function report(){game.screen='report';const end=game.state.ending,good=game.state.history.filter(h=>h.quality>=1).length;$('#app').innerHTML=translateHtml(`<div class="report fade-in"><div class="panel result"><p class="eyebrow">TU MISIÓN · RESULTADO FINAL</p><h1 class="${end.kind==='success'?'green':end.kind==='fatal'?'red':'orange'}">${end.kind==='success'?'¡MISIÓN CUMPLIDA!':end.kind==='fatal'?'MISIÓN PERDIDA':end.kind==='abort'?'REGRESO ANTICIPADO':'VOLVISTE CON VIDA'}</h1><p>${esc(end.reason)}</p>${game.state.demo?'<p class="mini">Demo: ocho casos estaban precargados; revisa el historial para distinguirlos de tus decisiones.</p>':''}<div class="flex mt"><span class="chip">${Math.min(12,game.state.turn+(game.state.feedback?1:0))}/12 casos</span><span class="chip">${good} respuestas fundamentadas</span><span class="chip">${game.state.photos.length} fotografías</span></div></div>${end.kind==='success'?'<section class="panel victory-scene"><canvas id="victoryScene" aria-label="Tripulación celebrando en la base lunar, enlace con la Tierra y nave lista para el regreso"></canvas><div class="victory-caption"><span class="eyebrow">MENSAJE DE CONTROL DE MISIÓN</span><h2>«Hallazgos recibidos. Buen trabajo, equipo.»</h2><p>Tu viaje terminó. Lo que aprendiste puede comenzar otra exploración.</p></div></section>':end.kind==='fatal'?'<div class="failure-scene panel"><canvas id="failureScene" aria-label="Escena de la misión perdida"></canvas><div class="failure-caption"><span class="eyebrow">ÚLTIMA SEÑAL RECIBIDA</span><p>Revisa el registro y prepara otra estrategia.</p></div></div>':'<div class="panel safe-return"><h2>La tripulación regresa.</h2><p>Un regreso con vida permite estudiar qué faltó y mejorar el siguiente viaje. Mira las metas y el registro para decidir qué cambiar.</p></div>'}${game.state.feedback?`<div class="panel last-choice">${verdictHtml(game.state.feedback.quality)}<p><b>Última decisión:</b> ${esc(game.state.feedback.choice)}</p><p>${esc(game.state.feedback.explain)}</p></div>`:''}${launchReportHtml()}<div class="mt">${hud()}</div><div class="report-grid"><div class="panel"><h3>Metas que conocías desde el inicio</h3><div class="requirements">${missionCriteria().map(([name,ok,value])=>`<p class="${ok?'ok':'bad'}">${ok?'✓':'○'} ${name}<br><small>${value}</small></p>`).join('')}</div><p class="mini">Las metas de arriba están visibles durante el viaje. Las respuestas fundamentadas se cuentan por caso; los puntos de valoración de los minijuegos no añaden un requisito oculto.</p></div><div class="panel"><h3>Para tu siguiente viaje</h3><ul>${game.state.r.science<MISSION_RULES.science?'<li>Registra ciencia en varias actividades y considera un instrumento o laboratorio.</li>':''}${game.state.r.comm<MISSION_RULES.comm?'<li>Reserva una recalibración o lleva apoyo de comunicaciones.</li>':''}${game.state.r.fuel<MISSION_RULES.fuel?'<li>Compara maniobras y considera un depósito o navegador de respaldo.</li>':''}${game.state.r.energy<20?'<li>Revisa las ventanas de luz y el uso de tus cargas eléctricas.</li>':''}${game.state.r.life<20?'<li>Compara reservas de soporte, reciclaje y protección según la ruta.</li>':''}<li>Intenta fundamentar al menos ocho decisiones: compara las condiciones con la explicación científica.</li><li>Una misma acción puede funcionar en un caso y fallar en otro.</li><li>La misión mejora cuando conectas las pistas científicas con tu decisión.</li></ul></div></div><div class="panel activity mt"><h3>Tu registro de exploración</h3>${game.state.history.map((h,i)=>`<div class="journal-entry" lang="es"><span class="orange">${i+1} · ${esc(h.actor||'Tripulación')}</span><b>${esc(h.title)} · ${esc(h.summary)}</b>${h.quality!==undefined?`<small>${verdict(h.quality).icon} ${verdict(h.quality).label}</small>`:''}${h.delta?`<small>${deltaText(h.delta)}</small>`:''}${h.notes?`<p>${esc(h.notes)}</p>`:''}${h.source?`<a class="source" target="_blank" rel="noopener" href="${SOURCES[h.source].url}">Fuente: ${esc(SOURCES[h.source].title)} ↗</a>`:''}</div>`).join('')}</div><div class="flex mt"><button class="primary continue-button" id="again">Preparar otro viaje →</button><button id="download">Descargar informe HTML</button><button id="album">Cuaderno y fotografías</button></div></div>`);$('#again').onclick=()=>start();$('#album').onclick=album;$('#download').onclick=download;syncContinueDock();syncProgress();window.scrollTo({top:0,behavior:reduced?'instant':'smooth'})}

export function drawVictory(canvas,t){const setup=canvasSetup(canvas);if(!setup)return;const{c,w,h}=setup;starfield(c,w,h,t);const earthX=w*.78,earthY=h*.22;ellipse(c,earthX,earthY,Math.min(42,w*.07),Math.min(42,w*.07),'#609ed4');ellipse(c,earthX-10,earthY-5,15,9,'#7accb1');ellipse(c,earthX+9,earthY+15,10,13,'#8bddbe');c.fillStyle='#65728e';c.beginPath();c.ellipse(w*.5,h*1.5,w*.85,h*.9,0,0,Math.PI*2);c.fill();ship(c,w*.22,h*.45,Math.min(.75,w/850),t,'hangar');astronaut(c,w*.48,h*.51,Math.min(1.15,w/650),t);astronaut(c,w*.63,h*.52,Math.min(1,w/700),t+.8);c.strokeStyle='#d9eaff';c.lineWidth=3;c.beginPath();c.moveTo(w*.76,h*.68);c.lineTo(w*.76,h*.40);c.stroke();c.fillStyle='#8be8bf';c.fillRect(w*.76,h*.40,w*.09,28);c.fillStyle='#143749';c.font='bold 15px system-ui';c.fillText(uiText('✓'),w*.78,h*.40+20);for(let i=0;i<4;i++){const r=24+((t*.18+i*.25)%1)*75;c.strokeStyle=`rgba(145,230,215,${.45*(1-(t*.18+i*.25)%1)})`;c.beginPath();c.arc(w*.76,h*.41,r,-1.6,-.4);c.stroke()}const g=c.createLinearGradient(0,h*.62,0,h);g.addColorStop(0,'#0b172500');g.addColorStop(1,'#0b1725ee');c.fillStyle=g;c.fillRect(0,0,w,h)}

export function hangarBrief(){ensureOffer();return `<section class="panel hangar-brief" aria-labelledby="hangarBriefTitle"><div class="hangar-brief-header"><div><p class="eyebrow">PREPARACIÓN DEL VIAJE · ALMACÉN ${esc(game.state.hangarCode)}</p><h3 id="hangarBriefTitle">Tu misión empieza con un buen plan.</h3><p>Instala los cuatro equipos básicos y elige hasta tres extras. Usa la previsión de la ruta y las metas para decidir qué llevar.</p><div class="hangar-limits"><span>${FLIGHT_BUDGET} créditos de presupuesto</span><span>${launcherProfile().maxMass} kg de carga máxima</span><span>${launcherProfile().cost} M de lanzamiento</span><span>${extraCount()}/3 extras a bordo</span></div></div><div class="hangar-brief-actions"><button class="primary" id="firstLoad">Mi primera nave →</button><button class="small" id="learnHelp">Cómo se juega</button><p>Una propuesta con el equipo disponible. Puedes cambiarla antes de despegar.</p></div></div>${launcherHtml()}${specialtyHtml()}<div class="hangar-brief-grid">${flightForecast()}${goalsHtml()}</div></section>`}

export function focusActivity(){const target=$('#challengePanel');target?.focus?.({preventScroll:true});target?.scrollIntoView?.({block:'start',behavior:reduced?'instant':'smooth'})}

export function activityResultContent(f){let summary=String(f.summary||'').trim();const oldScore=summary.match(/(\d+)\s*\/\s*(\d+)\s+respuestas\s+(?:correctas|fundamentadas)/i),score=f.score||(oldScore?{correct:+oldScore[1],total:+oldScore[2],label:'respuestas correctas'}:null);if(score){summary=summary.replace(/^(?:Atlas documentado:\s*)?\d+\s*\/\s*\d+\s+respuestas\s+(?:correctas|fundamentadas)(?:\s+en\s+[^.]+)?\.?\s*/i,'');summary=summary.replace(/Se conservan \d+ objetivos correctos\.?/i,'').trim()}for(const text of [QUICK_FACTS[f.source],SOURCES[f.source]?.fact].filter(Boolean))summary=summary.split(text).join('').trim();const normalize=text=>text.toLocaleLowerCase('es').replace(/\s+/g,' ').replace(/[.!?]+$/,'').trim(),mainFact=QUICK_FACTS[f.source]||SOURCES[f.source].fact;if(normalize(summary)===normalize(mainFact))summary='';const operational=/^(?:Tiempo agotado|La actividad|Sesión|Reto|Se agotaron)/i.test(summary);return{score,summary:!score||operational?summary:'',extraScience:score&&!operational?summary:''}}

export function activityFactHtml(f,extra){const source=SOURCES[f.source];return `<div class="fact"><b>DATO NASA · PARA APRENDER</b><p lang="es">${esc(QUICK_FACTS[f.source]||source.fact)}</p>${extra?`<p class="activity-context" lang="es"><b>En esta actividad:</b> ${esc(extra)}</p>`:''}<a class="source" href="${source.url}" target="_blank" rel="noopener">${esc(source.title)} ↗</a></div>`}

export function renderActivityResult(){game.screen='activityResult';const f=game.state.activityResult;if(!f)return;const content=activityResultContent(f);$('#app').innerHTML=translateHtml(`${hud()}<section class="panel activity-result" id="resultPanel" tabindex="-1"><p class="eyebrow">MINIJUEGO TERMINADO</p><div class="activity-result-heading"><h2>${esc(f.title)}</h2>${content.score?`<div class="result-score" aria-label="${content.score.correct} de ${content.score.total} respuestas correctas"><strong>${content.score.correct}<span>/${content.score.total}</span></strong><span>Respuestas correctas</span></div>`:''}</div>${verdictHtml(f.quality)}${resultExplanationHtml({explain:content.summary,protection:f.notes},false)}<h3>Qué cambió en tu nave</h3>${outcomeDeltas(f.delta)}${activityFactHtml(f,content.extraScience)}<button id="continueActivity" class="primary continue-button">Continuar · ${game.state.turn>=12?'ver resultado del viaje':'volver a la misión'} →</button></section>`);$('#continueActivity').onclick=continueActivityResult;syncProgress();syncContinueDock();focusResult()}

export function specialtyHtml(){return `<section class="specialty-picker" aria-labelledby="specialtyTitle"><h3 id="specialtyTitle">Tu especialidad · opcional</h3><p>Elige un apoyo pequeño para tu misión. Puedes cambiarlo antes del lanzamiento.</p><div>${Object.entries(SPECIALTIES).map(([id,s])=>`<button type="button" class="specialty-card role-${id}" data-specialty="${id}" aria-pressed="${(game.state.specialty||'none')===id}"><span class="specialty-card-top"><span class="specialty-insignia">${specialtyIcon(id)}</span><span class="specialty-selection"><span aria-hidden="true">${(game.state.specialty||'none')===id?'✓':'＋'}</span><span>${(game.state.specialty||'none')===id?'Elegida':'Elegir'}</span></span></span><strong>${esc(s.name)}</strong><span class="specialty-description">${esc(s.description)}</span></button>`).join('')}</div></section>`}

export function home(){game.screen='home';activityRuntime.activity=null;setEngineSound(false);$('#app').innerHTML=translateHtml(`<section class="hero fade-in"><div><p class="eyebrow">ARTEMIS MISSION LAB · APRENDE EXPLORANDO</p><h1>TU PRIMER<br>VIAJE A<br><span>LO DESCONOCIDO.</span></h1><p class="intro">Prepara tu nave, interpreta las pistas y aprende a completar una misión lunar. Antes de despegar puedes elegir una especialidad.</p><div class="hero-buttons"><button class="primary" id="startMission">Iniciar misión →</button><button class="secondary small" id="landingDemo">Demo rápida (Alunizaje)</button></div><p class="mini">36 situaciones · 12 por viaje · 7 de 11 minijuegos<br>Sin registro. Tu progreso se guarda en este navegador.</p><div class="mt" id="resumeBox"></div></div><div class="panel hero-scene"><canvas id="scene"></canvas><div class="scene-caption"><div><span class="eyebrow">DESTINO / 001</span><b>Polo sur lunar</b>Potencia · Supervivencia · Ciencia</div><span class="pill">SIMULACIÓN EDUCATIVA</span></div></div></section><section class="features"><div class="feature"><span class="num">01 / PREPARA</span><b>Construye tu capacidad.</b><p>Compara equipo, reservas y ruta antes de despegar.</p></div><div class="feature"><span class="num">02 / DECIDE</span><b>Lee las condiciones.</b><p>Relaciona las mediciones del caso con cada propuesta.</p></div><div class="feature"><span class="num">03 / EXPLORA</span><b>La ciencia se juega.</b><p>Fotografía, investiga el suelo y pilota el descenso.</p></div><div class="feature"><span class="num">04 / APRENDE</span><b>Con fuentes NASA.</b><p>Consulta la teoría a tu ritmo y lee la explicación después de elegir.</p></div></section><footer>Simulación educativa independiente · Hechos científicos citados y reglas ficticias diferenciados</footer>`);$('#startMission').onclick=()=>start();$('#landingDemo').onclick=startLandingDemo;try{if(localStorage.getItem('artemis-v3')){$('#resumeBox').innerHTML=translateHtml('<button class="secondary" id="resume">Continuar misión guardada</button>');$('#resume').onclick=restore}}catch{}}

export function scienceContext(e,open=false){return `<details class="case-science" ${open?'open':''}><summary>Qué nos enseña NASA · ${open?'explicación del caso':'consultar teoría'}</summary><p lang="es">${esc(e.scienceText)}</p>${e.hint?`<p class="case-application" lang="es"><b>Relación con el caso:</b> ${esc(e.hint)}</p>`:''}<a class="source" href="${SOURCES[e.source].url}" target="_blank" rel="noopener">Fuente oficial: ${esc(SOURCES[e.source].title)} ↗</a></details>`}

export function caseBrief(e){return `<article class="panel case-brief" id="caseBrief" aria-labelledby="caseTitle"><p class="eyebrow">CASO ${game.state.turn+1} DE 12 · ${esc(e.tag)}</p><h2 id="caseTitle">${esc(e.title)}</h2><p class="case-story" lang="es">${esc(e.narrative)}</p>${e.conditions?`<p class="case-readings"><b>Lecturas actuales:</b> ${esc(e.conditions)}</p>`:''}<div class="case-objective"><b>Tu tarea</b><p>${esc(e.objective)}</p></div>${difficultyBrief()}${advantagesHtml(e)}${scienceContext(e)}<p class="case-note">Las consecuencias se revelan después de decidir. Los costes y procedimientos de este caso son reglas de una simulación.</p></article>`}

export function feedbackHtml(){const f=game.state.feedback,e=event();return `<section class="panel feedback ${verdict(f.quality).tone}" id="resultPanel" tabindex="-1">${verdictHtml(f.quality)}<h2 class="mt">${esc(f.choice)}</h2>${resultExplanationHtml(f)}<h3>Qué cambió en tu nave</h3>${outcomeDeltas(f.delta)}${scienceContext(e,true)}<button class="primary continue-button" id="continue">Continuar · ${taskPlan()[game.state.turn+1]?'siguiente minijuego':'siguiente decisión'} →</button></section>`}

export function spectrumArt(p){const [lo,hi]=p.axis,x=n=>38+(n-lo)/(hi-lo)*324;let marks;if(p.id==='hydration'){marks=`<rect x="${x(2.8)}" y="25" width="${x(3)-x(2.8)}" height="49" fill="#9ee8d8" opacity=".65"/>`}else marks=p.bands.map(n=>`<line x1="${x(n)}" x2="${x(n)}" y1="25" y2="74" stroke="${p.kind==='channels'?'#edc58f':'#aca5ff'}" stroke-width="${p.kind==='channels'?4:13}" opacity=".8"/>`).join('');return `<svg class="lunar-spectrum" viewBox="0 0 400 110" role="img" aria-label="${esc(p.description)}"><rect x="38" y="25" width="324" height="49" rx="6" fill="#1d304c"/>${marks}<path d="M38 80H362" stroke="#9bb3cb"/>${[.3,1,2,3.2].map(n=>`<text x="${x(n)}" y="99" fill="#e0eaf8" font-size="11" text-anchor="middle">${n.toFixed(1)}</text>`).join('')}<text x="200" y="15" fill="#b7cbe6" font-size="10" text-anchor="middle">Longitud de onda (µm) · rasgos, no reflectancia medida</text></svg>`}

export function spectraUI(){const a=activityRuntime.activity;a.spectraOrder ||= shuffle([0,1,2]);const p=SPECTRAL_PATTERNS[a.spectraOrder[a.round]];$('#activityContent').innerHTML=translateHtml(`<p class="eyebrow">MINERALOGÍA LUNAR · MUESTRA ${a.round+1}/3</p><h3>Relaciona el rasgo con su referencia científica</h3><div class="spectrum-sample">${spectrumArt(p)}<p>${esc(p.description)}</p></div><div class="spectra-options">${shuffle([0,1,2]).map(i=>`<button data-spectrum="${i}"><b>${esc(SPECTRAL_PATTERNS[i].name)}</b>${spectrumArt(SPECTRAL_PATTERNS[i])}<p>${esc(SPECTRAL_PATTERNS[i].description)}</p></button>`).join('')}</div><p class="mini">Rasgos y canales reales tomados de referencias NASA; geometría y anchura de las marcas simplificadas. No son espectros medidos ni identifican inequívocamente una muestra real.</p><div id="newTaskFeedback" aria-live="polite"></div>`);document.querySelectorAll('[data-spectrum]').forEach(b=>b.onclick=()=>answerSpectrum(+b.dataset.spectrum));if(a.locked&&a.review)renderRoundReview()}

export function roverUI(){activityRuntime.activity.rover ||= makeRoverMap();const r=activityRuntime.activity.rover;$('#activityContent').innerHTML=translateHtml(`<div class="shackleton-context"><h3>Explora el entorno de Shackleton</h3><p>NASA distingue zonas muy iluminadas del borde y un interior en sombra permanente. La iluminación del borde no es uniforme ni constante en todos sus puntos.</p><p class="mini">Este tablero aleatorio es un esquema inspirado en ese contraste, no un mapa topográfico medido ni una ruta real.</p></div><div class="rover-legend"><span>☀ Borde iluminado · 1</span><span>◐ Sombra · 2</span><span>◆ Obstáculo</span><span>⌂ Base del reto</span></div><div class="rover-board" role="group" aria-label="Esquema del entorno de Shackleton, cinco por cinco casillas">${r.cells.map((kind,i)=>`<button data-rover="${i}" class="tile-${kind} ${r.path.includes(i)?'visited':''} ${i===r.pos?'rover-here':''}" aria-label="Fila ${Math.floor(i/5)+1}, columna ${i%5+1}: ${i===r.pos?'rover':i===24?'base':kind==='rock'?'obstáculo':kind==='shadow'?'sombra':'iluminado'}" ${kind==='rock'?'disabled':''}>${i===r.pos?'▣':i===24?'⌂':kind==='rock'?'◆':kind==='shadow'?'◐':'·'}</button>`).join('')}</div><p id="roverStatus" class="task-hint" role="status">Batería del reto ${r.battery}/12 · ${r.moves} movimientos. Usa flechas, WASD o toca una casilla vecina.</p><button id="leaveNewTask" class="primary continue-button">Terminar con el avance actual →</button>`);document.querySelectorAll('[data-rover]').forEach(b=>b.onclick=()=>moveRover(+b.dataset.rover));$('#leaveNewTask').onclick=()=>completeActivity({energy:-2,science:0},'shackleton','Ruta interrumpida antes de llegar a la base.',0)}

export function landingUI(){const l=activityRuntime.activity.lander;l.x ??=450;l.vx ??=0;l.startFuel ??=l.fuel;l.left=false;l.right=false;l.thrust=false;$('#activityContent').innerHTML=translateHtml('<canvas id="taskCanvas" width="900" height="340" aria-label="Alunizaje 2D: corrige posición horizontal y frena el descenso"></canvas><div class="readout" id="taskReadout">PREPARADO · Inicia el descenso cuando hayas leído los controles.</div><div class="controls landing-controls"><button id="startLanding" class="primary">Iniciar descenso</button><button id="leftThrust" disabled>← Corregir izquierda</button><button id="thrust" disabled>↑ MOTOR · Espacio</button><button id="rightThrust" disabled>Corregir derecha →</button><button id="endTask">Cancelar descenso</button></div><p class="task-hint">Flechas ←/→ corrigen la velocidad lateral; Espacio o ↑ frenan la caída. Suelta los propulsores para avanzar por inercia. Aterriza dentro de la zona marcada, con velocidad vertical menor de 12 m/s y lateral no mayor de 3 m/s.</p><p class="mini">Gravedad lunar 1,62 m/s². Vehículo, combustible, escala, umbrales y zona segura son reglas del simulador. La deriva inicial es inercial; no hay viento atmosférico lunar.</p>');const enable=()=>{l.started=true;activityRuntime.activity.lastClock=null;$('#startLanding').disabled=true;for(const id of ['leftThrust','thrust','rightThrust'])$('#'+id).disabled=false};$('#startLanding').onclick=enable;if(l.started)enable();for(const [id,key]of [['leftThrust','left'],['thrust','thrust'],['rightThrust','right']]){const button=$('#'+id);button.onpointerdown=e=>{e.preventDefault();if(activityRuntime.activity?.type!=='landing'||!l.started||activityRuntime.activity.done)return;l[key]=true;try{e.currentTarget.setPointerCapture(e.pointerId)}catch{}};for(const name of ['onpointerup','onpointercancel','onlostpointercapture'])button[name]=()=>{l[key]=false}}$('#endTask').onclick=()=>{releaseLandingControls();completeActivity({fuel:Math.round(l.fuel-l.startFuel),science:0,hull:-8},'gravity','Descenso cancelado. Se conserva la reserva de regreso y se registra el propelente utilizado.',-1)}}

export function drawLanding(c,w,h,dt,t){stepLanding(dt);if(activityRuntime.activity?.type!=='landing')return;const l=activityRuntime.activity.lander;c.fillStyle='#4d6175';c.fillRect(0,300,w,40);c.fillStyle='#2c504b';c.fillRect(LANDING.padX-LANDING.padHalfWidth,296,LANDING.padHalfWidth*2,4);c.fillStyle='#8ce6be';c.fillRect(LANDING.padX-LANDING.safeHalfWidth,292,LANDING.safeHalfWidth*2,8);c.strokeStyle='#8ce6be66';c.setLineDash([5,8]);for(const x of [LANDING.padX-LANDING.safeHalfWidth,LANDING.padX+LANDING.safeHalfWidth]){c.beginPath();c.moveTo(x,25);c.lineTo(x,292);c.stroke()}c.setLineDash([]);drawLandingDust(c,l,t);c.save();c.translate(l.x,l.y);c.fillStyle='#dbe6ed';c.fillRect(-22,-15,44,29);c.fillStyle='#6db0d1';c.fillRect(-11,-10,22,12);c.strokeStyle='#b6c8d9';c.lineWidth=4;c.beginPath();c.moveTo(-20,10);c.lineTo(-34,28);c.moveTo(20,10);c.lineTo(34,28);c.stroke();if(l.thrust&&l.fuel>0){c.fillStyle='#ffb36a';c.beginPath();c.moveTo(-12,14);c.lineTo(0,48+Math.sin(t*30)*5);c.lineTo(12,14);c.fill()}if(l.fuel>0&&(l.left||l.right)){c.fillStyle='#91dbff';c.fillRect(l.left?24:-42,-3,18,5)}c.restore()}

export function advantagesHtml(e){const benefits=activeAdvantages(e);return benefits.length?`<p class="mini"><b>Ventajas disponibles en este caso:</b> ${benefits.map(name=>`<span>${esc(name)}</span>`).join(' · ')}. <span>Se aplican según la acción elegida.</span></p>`:''}

export function drawLandingDust(c,l,t){if(reduced||!l.started||!l.thrust||l.fuel<=0||l.y<=215)return;const strength=clamp((l.y-215)/50,.12,1);c.save();for(let i=0;i<28;i++){const age=(t*1.2+i*.6180339)%1,side=i%2?1:-1,reach=age*(30+strength*65),height=age*(16+i%5*6)-age*age*12;c.globalAlpha=(1-age)*strength*.45;ellipse(c,l.x+side*reach,296-height,1.5+age*2.5,1+age*.8,'#b5b5ad')}c.restore()}

export function showCinema(type,title,text,callback,soundCue=null){if(game.cinema)return;game.cinema={type,title,text,callback,t:0,duration:reduced?.3:type==='death'?4.5:type==='success'?5:2.8};$('#cinema').classList.remove('hidden');$('#cinemaTag').textContent=uiText(type==='death'?'ÚLTIMA TELEMETRÍA':type==='success'?'CIENCIA · EQUIPO · REGRESO':'SECUENCIA DE MISIÓN');$('#cinemaTitle').textContent=uiText(title);$('#cinemaText').textContent=uiText(text);$('#skipCinema').onclick=endCinema;playCinemaSound(type,soundCue)}

export function specialtyIcon(id){
 const paths={none:'<path d="M7 20v-5a5 5 0 0 1 10 0v5M6 20h12M9 13h6M10 17h4"/><circle cx="12" cy="7" r="4"/>',commander:'<circle cx="12" cy="12" r="9"/><path d="m15 9-2 4-4 2 2-4 4-2ZM12 1v3M12 20v3M1 12h3M20 12h3"/>',eclss:'<path d="M12 2C10 6 5 10 5 14a7 7 0 0 0 14 0c0-4-5-8-7-12Z"/><path d="M8 14h3l1-3 2 6 1-3h2"/>',science:'<path d="M16 3a9 9 0 1 0 5 14A9 9 0 0 1 16 3Z"/><path d="M20 2v6M17 5h6M13 9v4M11 11h4"/>'};
 return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">${paths[id]||paths.none}</svg>`;
}

export function specialtyBadge(){const id=SPECIALTIES[game.state?.specialty]?game.state.specialty:'none';return `<span class="specialty-badge role-${id}">${specialtyIcon(id)}<span>${esc(crewName())}</span></span>`}

export function resultExplanationHtml(f,includeGoal=true){
 const notes=String(f.protection||'').replace('Comandante: una unidad de propelente conservada.','Tu especialidad de Comandante conservó 1 unidad de propelente.').replace('ECLSS: una unidad de desgaste vital evitada.','Tu especialidad de Ingeniería ECLSS evitó 1 unidad de desgaste del soporte vital.').replace('Ciencia Lunar: un punto de documentación adicional.','Tu especialidad de Ciencia Lunar añadió 1 punto de ciencia al registro.');
 const sentences=[f.explain,notes,includeGoal?(f.quality>=1?'Esta decisión cuenta para la meta de casos fundamentados.':'Aprendizaje registrado. Esta respuesta no completa la meta del caso.'):''].map(text=>String(text||'').trim()).filter(Boolean);
 return sentences.length?`<section class="result-explanation" aria-label="${esc(uiText('Tu decisión, explicada'))}"><h3>Tu decisión, explicada</h3><p>${sentences.map(text=>`<span>${esc(text)}</span>`).join(' ')}</p></section>`:'';
}

export function launcherHtml(){const selected=launcherProfile();return `<section class="launcher-picker" aria-labelledby="launcherTitle"><h3 id="launcherTitle">Primero, elige cómo despegar</h3><p>El lanzamiento se paga una sola vez de tus ${FLIGHT_BUDGET} M. Después compras módulos y conservas una reserva para operar.</p><div class="launcher-grid">${Object.values(LAUNCHERS).map(p=>`<button type="button" class="launcher-card ${selected.id===p.id?'selected':''}" data-launcher="${p.id}" aria-pressed="${selected.id===p.id}" style="--launcher-color:${p.color}"><span class="launcher-heading"><span class="launcher-symbol" aria-hidden="true">${p.id==='light'?'▴':p.id==='medium'?'▴▴':'▴▴▴'}</span><span>${selected.id===p.id?'✓ Elegido':'Elegir'}</span></span><strong>${p.name}</strong><span class="launcher-values"><b>${p.maxMass} kg</b><b>${p.cost} M</b></span><span>${p.description}</span><small>${FLIGHT_BUDGET-p.cost} M para equipo y operación</small></button>`).join('')}</div><p class="mini launcher-fiction">Perfiles ficticios del juego: estas capacidades y tarifas no son prestaciones ni precios reales de vehículos NASA. La masa representa la carga de la nave, no la masa del cohete.</p></section>`}

export function launcherSummary(){const p=launcherProfile(),budget=game.state.balanceVersion>=29?FLIGHT_BUDGET:100,fee=game.state.balanceVersion>=29?p.cost:0;return `<div class="launcher-summary"><b>${esc(p.name)}</b><span>${game.state.mass} / ${p.maxMass} kg · ${fee} M de lanzamiento</span><span>${budget-fee} M antes de comprar equipo</span><p class="mini">${game.state.balanceVersion>=29?'Cada lanzamiento se descuenta una sola vez.':'Partida anterior: se conserva el presupuesto original, sin nueva tarifa.'}</p></div>`}

export function difficultyBrief(){const d=operatingCost(),next=taskPlan()[game.state.turn+1];return `<p class="difficulty-brief"><b>Demanda de esta fase</b><span>${esc(deltaText(d))} por decisión.</span><span>Un error añade desgaste; un minijuego resuelto aporta 2 M. Reglas del simulador.</span>${next?`<span><b>Después de este caso:</b> ${esc(ACTIVITY_CONFIG[next].title)}. ${next==='landing'?`El descenso puede usar hasta 24 unidades de propelente; conserva otras ${MISSION_RULES.fuel} para regresar.`:'Comprueba tus reservas antes de elegir.'}</span>`:''}</p>`}

export function drawLaunchPreview(c,w,h,t){const p=launcherProfile(),x=w/2,y=h*.43,scale=Math.min(.7,w/360);c.save();c.translate(x,y);c.scale(scale,scale);c.fillStyle='#9bafc7';c.fillRect(-23,0,46,117);c.fillStyle=p.color;c.fillRect(-23,22,46,10);c.fillStyle='#31455e';c.fillRect(-28,110,56,10);const boosters=p.id==='heavy'?[-57,-36,36,57]:p.id==='medium'?[-40,40]:[];for(const bx of boosters){c.fillStyle='#cfdae6';c.beginPath();c.moveTo(bx-9,105);c.lineTo(bx-9,18);c.lineTo(bx,1);c.lineTo(bx+9,18);c.lineTo(bx+9,105);c.closePath();c.fill();c.fillStyle=p.color;c.fillRect(bx-9,72,18,9)}c.restore();if(has('capsule'))ship(c,x,y-26,Math.min(.58,w/440),t,'hangar');else{c.fillStyle='#c3d3e5';c.font='12px system-ui';c.textAlign='center';c.fillText(uiText('Añade la cápsula para completar tu nave'),x,28)}}

export function launchReportHtml(){const p=launcherProfile(),legacy=game.state.balanceVersion<29,s=game.state.launchSnapshot||{...launchRecord(),budget:legacy?100:FLIGHT_BUDGET,cost:legacy?0:p.cost};if(!game.state.launchSnapshot)s.operatingReserve=s.budget-s.cost-s.equipmentCost;return `<section class="launch-report"><h2>${esc(uiText('Vehículo y carga de lanzamiento'))}</h2><p><b>${esc(uiText(s.name))}</b> · ${s.mass} / ${s.maxMass} kg <span>${uiText('de carga')}</span></p><p><span>${uiText('Presupuesto inicial:')}</span> ${s.budget} M · <span>${uiText('Lanzamiento:')}</span> ${s.cost} M · <span>${uiText('Equipo:')}</span> ${s.equipmentCost} M</p><p><span>${uiText('Reserva al despegar:')}</span> ${s.operatingReserve} M. <span>${uiText('La tarifa no se vuelve a cobrar durante el viaje.')}</span></p><p class="muted">${uiText('Perfiles, créditos, masa de carga y capacidades son abstracciones del simulador, no datos de rendimiento de un cohete real.')}</p></section>`}
